        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        notificationPrefs = prefs;
        ShowToast("Notification preferences saved!", "success");
    }

    private void ToggleChannelMute(string channel, ChangeEventArgs e)
    {
        var isMuted = (bool)(e.Value ?? false);
        if (isMuted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!isMuted)
            mutedChannels.Remove(channel);
    }

    // Security actions
    private async Task UpdatePassword()
    {
        if (newPassword != confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("All password fields are required.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        changePasswordExpanded = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevokeSession(string sessionId)
    {
        sessionToRevoke = sessionId;
        showRevokeConfirmation = true;
    }

    private async Task ConfirmRevoke()
    {
        if (sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            showRevokeConfirmation = false;
            sessionToRevoke = null;
            ShowToast("Session revoked.", "success");
        }
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        appearanceSettings = settings;
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        toastTimer?.Dispose();
        toastTimer = new System.Timers.Timer(3000);
        toastTimer.Elapsed += (_, _) =>
        {
            toastMessage = null;
            InvokeAsync(StateHasChanged);
            toastTimer?.Dispose();
        };
        toastTimer.AutoReset = false;
        toastTimer.Start();
    }

    // Render methods
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile Settings</h2>

            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(profileAvatarUrl))
                {
                    <img src="@profileAvatarUrl" alt="Avatar" class="avatar-image" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <span class="avatar-url-display">@profileAvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="profileDisplayName" class="form-control" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="profileEmail" class="form-control" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="profileBio" class="form-control" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notification Preferences</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="emailNotifications" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="pushNotifications" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="weeklyDigest" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="(e) => ToggleChannelMute(channel, e)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security Settings</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => changePasswordExpanded = !changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(changePasswordExpanded ? "▼" : "▶")</span>
                </button>
                @if (changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="currentPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="newPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm New Password</label>
                            <input id="confirmPwd" type="password" @bind="confirmPassword" class="form-control" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="security-item">
                <div class="two-factor-row">
                    <span>Two-Factor Authentication</span>
                    <span class="status-indicator @(securitySettings?.TwoFactorEnabled == true ? "enabled" : "disabled")">
                        @(securitySettings?.TwoFactorEnabled == true ? "✓ Enabled" : "✗ Disabled")
                    </span>
                </div>
                @if (securitySettings?.LastPasswordChange is not null)
                {
                    <p class="text-muted">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <h3>Active Sessions</h3>
            @if (securitySettings?.Sessions is { Count: > 0 })
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != securitySettings.Sessions.First())
                                    {
                                        <button class="btn btn-danger btn-sm" @onclick="() => RequestRevokeSession(session.Id)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-session-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            }
            else
            {
                <p class="text-muted">No active sessions found.</p>
            }
        </section>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance Settings</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Light" @onchange='() => selectedTheme = "Light"' checked="@(selectedTheme == "Light")" />
                        Light
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Dark" @onchange='() => selectedTheme = "Dark"' checked="@(selectedTheme == "Dark")" />
                        Dark
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="System" @onchange='() => selectedTheme = "System"' checked="@(selectedTheme == "System")" />
                        System
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Small" @onchange='() => selectedFontSize = "Small"' checked="@(selectedFontSize == "Small")" />
                        Small
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Medium" @onchange='() => selectedFontSize = "Medium"' checked="@(selectedFontSize == "Medium")" />
                        Medium
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Large" @onchange='() => selectedFontSize = "Large"' checked="@(selectedFontSize == "Large")" />
                        Large
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="selectedLanguage" class="form-control">
                    @foreach (var lang in languages)
                    {
                        <option value="@lang.Code">@lang.Name</option>
                    }
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="compactMode" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Compact Mode
                </label>
            </div>

            <h3>Live Preview</h3>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Preview Area</div>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>A sample card element showing theme and spacing.</p>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{selectedTheme.ToLowerInvariant()}");
        classes.Add($"preview-font-{selectedFontSize.ToLowerInvariant()}");
        if (compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    public void Dispose()
    {
        toastTimer?.Dispose();
    }
}

